struct UnsafeOutput {
  static constexpr int bufsz = 1 << 16;
 
  UnsafeOutput() {
    for (int x = 0; x < 1000; ++x) {
      rep[3 * x] = x / 100 + '0';
      rep[3 * x + 1] = x / 10 % 10 + '0';
      rep[3 * x + 2] = x % 10 + '0';
    }
  }
 
  void flush() {
    fwrite(buf, 1, bufptr - buf, stdout);
    bufptr = buf;
  }
 
  void operator<<(uint32_t x) {
    if (std::end(buf) - bufptr < 10) flush();
    auto st = bufptr, ptr = bufptr += 10;
    ptr[-1] = '\n';
    #pragma GCC unroll 99
    for (int i = 0; i < 3; ++i, ------ptr) {
      ptr[-4] = rep[x % 1000 * 3 + 0];
      ptr[-3] = rep[x % 1000 * 3 + 1];
      ptr[-2] = rep[x % 1000 * 3 + 2];
      if (x < 1000) {
        ptr += (x < 10) + (x < 100);
        break;
      }
      x /= 1000;
    }
    std::fill(st, ptr - 4, ' ');
  }
 
  ~UnsafeOutput() { flush(); }
 
  char rep[3000];
  alignas(64) char buf[bufsz];
  char *bufptr = buf;
} writer;

